import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        s = next(iterator)

        # Try each character from 'a' to 'z' as the candidate to remove
        min_erased = float('inf')

        for char_code in range(ord('a'), ord('z') + 1):
            target_char = chr(char_code)

            # Check if removing some occurrences of target_char makes s a palindrome
            # We use two pointers approach
            left = 0
            right = n - 1
            removed_count = 0

            possible = True

            while left < right:
                if s[left] == s[right]:
                    left += 1
                    right -= 1
                else:
                    # Mismatch found
                    # Try to skip the character on the left if it matches target_char
                    if s[left] == target_char:
                        left += 1
                        removed_count += 1
                    # Try to skip the character on the right if it matches target_char
                    elif s[right] == target_char:
                        right -= 1
                        removed_count += 1
                    else:
                        # Neither side matches target_char, so we cannot fix this mismatch
                        possible = False
                        break

            if possible:
                if removed_count < min_erased:
                    min_erased = removed_count

        if min_erased == float('inf'):
            results.append("-1")
        else:
            results.append(str(min_erased))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
